        .clk(clk),
        .areset(areset),
        .in(in),
        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // Task to check output
    task check_out(input expected);
        begin
            if (out !== expected) begin
                $display("ERROR at time %0t: out = %b, expected = %b", $time, out, expected);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize inputs
        clk = 0;
        areset = 1;
        in = 0;

        // Verify async reset immediately puts machine into State B (out = 1)
        #2;
        check_out(1'b1);

        // Release reset aligned to clock
        @(negedge clk);
        areset = 0;
        check_out(1'b1); // Still in B

        // In State B, input 1 -> remain in B (out = 1)
        in = 1;
        @(posedge clk);
        #1;
        check_out(1'b1);

        // In State B, input 0 -> transition to A (out = 0)
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b0);

        // In State A, input 1 -> remain in A (out = 0)
        @(negedge clk);
        in = 1;
        @(posedge clk);
        #1;
        check_out(1'b0);

        // In State A, input 0 -> transition to B (out = 1)
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b1);

        // Transition back to A
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b0);

        // Test asynchronous reset while in State A (out should become 1 immediately)
        #2;
        areset = 1;
        #1;
        check_out(1'b1);

        // Release reset and verify continued operation
        @(negedge clk);
        areset = 0;
        in = 1;
        @(posedge clk);
        #1;
        check_out(1'b1);

        // Final transition to A
        @(negedge clk);
        in = 0;
        @(posedge clk);
        #1;
        check_out(1'b0);

        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
